import { createServer } from 'node:http';

const tasks = [{ id: 1, title: 'Write the report', done: false }];

function sendJson(res, status, body) {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

const server = createServer((req, res) => {
  const { pathname } = new URL(req.url, 'http://localhost');
  if (pathname === '/api/tasks' && req.method === 'GET') return sendJson(res, 200, tasks);
  if (pathname === '/api/tasks') {
    res.setHeader('allow', 'GET');
    return sendJson(res, 405, { error: `${req.method} is not allowed here` });
  }
  sendJson(res, 404, { error: `No route for ${pathname}` });
});

server.listen(3000, () => console.log('Listening on http://localhost:3000'));

async function createTask(title) {
  const response = await fetch('http://localhost:3000/api/tasks', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ title }),
  });
  // fetch only rejects when the network fails: a 400 or a 500 arrives here too.
  if (!response.ok) {
    const { error } = await response.json();
    throw new Error(`Could not create the task (${response.status}): ${error}`);
  }
  console.log('Created at', response.headers.get('location')); // Created at /api/tasks/2
  return response.json();
}

import express from 'express';

const tasks = express.Router();
const store = new Map([[1, { id: 1, title: 'Write the report', done: false }]]);
let nextId = 2;

tasks.get('/', (req, res) => {
  res.json([...store.values()]);
});

tasks.get('/:id', (req, res) => {
  const task = store.get(Number(req.params.id)); // params are always strings
  if (!task) return res.status(404).json({ error: `No task ${req.params.id}` });
  res.json(task);
});

tasks.post('/', (req, res) => {
  const task = { id: nextId++, title: req.body.title, done: false };
  store.set(task.id, task);
  res.status(201).location(`/api/tasks/${task.id}`).json(task);
});

const app = express();
app.use(express.json());
app.use('/api/tasks', tasks);
app.listen(3000);

