import express from 'express';

const app = express();

// Runs first for every request: gives it an id that shows in the logs and in the answer.
app.use((req, res, next) => {
  req.id = randomUUID();
  res.set('x-request-id', req.id);
  next();
});

// Runs second: logs each request once the answer has been sent.
app.use((req, res, next) => {
  const started = performance.now();
  res.on('finish', () => {
    const ms = Math.round(performance.now() - started);
    console.log(`${req.id} ${req.method} ${req.originalUrl} → ${res.statusCode} in ${ms}ms`);
  });
  next();
});

app.use(express.json({ limit: '10kb' }));

app.get('/api/health', (req, res) => {
  res.json({ ok: true });
});

app.listen(3000);

import express from 'express';

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

const db = { findTask: async (id) => (id === 1 ? { id: 1, title: 'Write the report' } : null) };
const app = express();

// No try/catch: in Express 5 a rejected promise goes to the error handler by itself.
app.get('/api/tasks/:id', async (req, res) => {
  const task = await db.findTask(Number(req.params.id));
  if (!task) throw new HttpError(404, `No task ${req.params.id}`);
  res.json(task);
});

// Nothing else matched.
app.use((req, res) => {
  res.status(404).json({ error: `No route for ${req.method} ${req.path}` });
});

// Four parameters make it the error handler. It goes last.
app.use((err, req, res, next) => {
  const status = err.status ?? 500;
  if (status >= 500) console.error(err);
  res.status(status).json({ error: status >= 500 ? 'Something went wrong' : err.message });
});

app.listen(3000);

