/** One message per field, for a form to show beside each input. */
function fieldErrors(error) {
  const fields = {};
  for (const issue of error.issues) fields[issue.path.join('.') || 'body'] ??= issue.message;
  return fields;
}

/** Checks req.body against `schema`, and replaces it with the parsed, cleaned data. */
function validate(schema) {
  return (req, res, next) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      return res.status(400).json({ error: 'Check the fields and try again', fields: fieldErrors(result.error) });
    }
    req.body = result.data;
    next();
  };
}

