// `db` is a pg Pool: new Pool({ connectionString: process.env.DATABASE_URL })

export async function findTasks(db, { projectId, search = '', limit = 20 }) {
  const { rows } = await db.query(
    `SELECT id, title, done FROM tasks
      WHERE project_id = $1 AND title ILIKE $2
      ORDER BY created_at
      LIMIT $3`,
    [projectId, `%${search}%`, limit],
  );
  return rows;
}

export async function createTask(db, { projectId, title }) {
  const { rows } = await db.query('INSERT INTO tasks (project_id, title) VALUES ($1, $2) RETURNING id, title, done', [
    projectId,
    title,
  ]);
  return rows[0];
}

/** True when a task was marked done; false when there is no such task. */
export async function completeTask(db, id) {
  const { rowCount } = await db.query('UPDATE tasks SET done = true WHERE id = $1', [id]);
  return rowCount === 1;
}

// N+1: one query for the projects, then one more for each project. 50 projects, 51 round trips.
async function projectsWithTasksSlow(db) {
  const { rows: projects } = await db.query('SELECT id, name FROM projects ORDER BY name');
  for (const project of projects) {
    const { rows } = await db.query('SELECT id, title FROM tasks WHERE project_id = $1 ORDER BY id', [project.id]);
    project.tasks = rows;
  }
  return projects;
}

// One query: Postgres builds each project's task list itself.
async function projectsWithTasks(db) {
  const { rows } = await db.query(`
    SELECT p.id, p.name,
           coalesce(json_agg(json_build_object('id', t.id, 'title', t.title) ORDER BY t.id)
                    FILTER (WHERE t.id IS NOT NULL), '[]') AS tasks
      FROM projects p
      LEFT JOIN tasks t ON t.project_id = p.id
     GROUP BY p.id, p.name
     ORDER BY p.name`);
  return rows;
}

import { randomBytes, scrypt, timingSafeEqual } from 'node:crypto';
import { promisify } from 'node:util';

const scryptAsync = promisify(scrypt);

export async function hashPassword(password) {
  const salt = randomBytes(16);
  const hash = await scryptAsync(password, salt, 32);
  return `${salt.toString('hex')}:${hash.toString('hex')}`;
}

export async function verifyPassword(password, stored) {
  const [salt, hash] = stored.split(':');
  const expected = Buffer.from(hash, 'hex');
  const actual = await scryptAsync(password, Buffer.from(salt, 'hex'), expected.length);
  return timingSafeEqual(actual, expected);
}

const stored = await hashPassword('correct horse battery staple');
console.log(stored); // 'a3f1…:9c0e…', different every time, because the salt is random
console.log(await verifyPassword('correct horse battery staple', stored)); // true
console.log(await verifyPassword('Correct horse battery staple', stored)); // false

import { createHash, randomBytes } from 'node:crypto';

app.post('/api/sign-in', async (req, res) => {
  const { email, password } = req.body; // already checked by a schema
  const user = await db.findUserByEmail(email.toLowerCase());
  // One answer for both mistakes, so nobody can learn which emails have accounts.
  if (!user || !(await verifyPassword(password, user.passwordHash))) {
    return res.status(401).json({ error: 'That email and password do not match an account' });
  }
  const token = randomBytes(32).toString('base64url');
  const tokenHash = createHash('sha256').update(token).digest('hex');
  await db.createSession({ tokenHash, userId: user.id, expiresInDays: 30 });
  res.cookie('session', token, { httpOnly: true, secure: true, sameSite: 'lax', maxAge: 30 * 24 * 60 * 60 * 1000 });
  res.json({ user: { id: user.id, name: user.name } });
});

function requireRole(...roles) {
  return (req, res, next) => {
    if (!req.user) return res.status(401).json({ error: 'Sign in first' });
    if (!roles.includes(req.user.role)) return res.status(403).json({ error: 'You cannot do that' });
    next();
  };
}

// Only admins can delete a project.
app.delete('/api/projects/:id', requireRole('admin'), async (req, res) => {
  await db.query('DELETE FROM projects WHERE id = $1', [req.params.id]);
  res.status(204).end();
});

// Anyone signed in can edit a task, but only their own: the check is part of the query.
app.patch('/api/tasks/:id', requireRole('member', 'admin'), async (req, res) => {
  const { rowCount } = await db.query('UPDATE tasks SET title = $1 WHERE id = $2 AND owner_id = $3', [
    req.body.title,
    req.params.id,
    req.user.id,
  ]);
  if (rowCount === 0) return res.status(404).json({ error: 'No such task' }); // not "forbidden": don't confirm it exists
  res.status(204).end();
});
